<form action="request-action" method="post" class="request-form" data-safe-draft="request-<?= e($request['id']??'new') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="request.<?= isset($request)?'update':'create' ?>"><?php if(isset($request)):?><input type="hidden" name="id" value="<?= e($request['id']) ?>"><?php endif;?><label class="full">Request title<input name="title" value="<?= e($request['title']??'') ?>" required maxlength="255"></label><label>Equipment type<select name="equipment_type_id" required><option value="">Choose type</option><?php foreach($types as $option):?><option value="<?= e($option['id']) ?>" <?= ($request['equipment_type_id']??'')===$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label>Commercial intent<select name="intent"><?php foreach(['LEASE','PURCHASE','EITHER'] as $option):?><option <?= ($request['intent']??'LEASE')===$option?'selected':'' ?>><?= $option ?></option><?php endforeach;?></select></label><label>Category<select name="category_id"><option value="">Optional</option><?php foreach($categories as $option):?><option value="<?= e($option['id']) ?>" <?= ($request['category_id']??'')===$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label>Subcategory<select name="subcategory_id"><option value="">Optional</option><?php foreach($subcategories as $option):?><option value="<?= e($option['id']) ?>" <?= ($request['subcategory_id']??'')===$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label>Quantity<input type="number" min="1" name="quantity_required" value="<?= (int)($request['quantity_required']??1) ?>" required></label><label>Required location<select name="required_location_id" required><option value="">Choose location</option><?php foreach($locations as $option):?><option value="<?= e($option['id']) ?>" <?= ($request['required_location_id']??'')===$option['id']?'selected':'' ?>><?= e($option['canonical_name'].($option['country_name']?' · '.$option['country_name']:'')) ?></option><?php endforeach;?></select></label><label>Required from<input type="date" name="required_from" value="<?= e($request['required_from']??'') ?>" required></label><label>Required until<input type="date" name="required_until" value="<?= e($request['required_until']??'') ?>"></label><label>Response deadline<input type="datetime-local" name="response_deadline" value="<?= e(isset($request)?date('Y-m-d\TH:i',strtotime($request['response_deadline'])):'') ?>" required></label><label>Visibility<select name="visibility"><option value="PUBLIC" <?= ($request['visibility']??'PUBLIC')==='PUBLIC'?'selected':'' ?>>Public Marketplace</option><option value="PRIVATE" <?= ($request['visibility']??'')==='PRIVATE'?'selected':'' ?>>Private</option></select></label><label class="full">Short description<textarea name="description" required><?= e($request['description']??'') ?></textarea></label><label class="full">Core specifications <small>One per line, for example: Capacity: 20 tonnes</small><textarea name="core_specifications"><?php foreach(json_decode($request['core_specifications']??'{}',true)?:[] as $key=>$value)echo e($key.': '.$value)."\n";?></textarea></label><label>OEM preference<input name="oem_preference" value="<?= e($request['oem_preference']??'') ?>"></label><label>Model preference<input name="model_preference" value="<?= e($request['model_preference']??'') ?>"></label><label class="full">Required certifications/documents<textarea name="required_documents"><?= e($request['required_documents']??'') ?></textarea></label><label class="check full"><input type="checkbox" name="alternatives_accepted" value="1" <?= !isset($request)||!empty($request['alternatives_accepted'])?'checked':'' ?>> Alternatives accepted</label><div class="full"><button name="publish" value="1" class="market-button"><?= isset($request)?'Save request':'Publish request' ?></button><?php if(!isset($request)):?> <button>Save draft</button><?php endif;?></div></form>
